<script setup lang="ts">
import { useToastNotice } from "./toast";
import {ref,watch} from 'vue';
import {api,t,date,errorText,session} from './lib';
import {usePageSize} from './page-size';
import {refundFailureKind} from "./refund-status";
import QueryControls from './QueryControls.vue';
const props=defineProps<{refreshToken:any}>();
const rows=ref<any[]>([]),search=ref(''),applied=ref(''),page=ref(0),size=usePageSize(),total=ref(0),busy=ref(false),error=ref(''),notice=useToastNotice('info');
const selected=ref<any>(null),quote=ref<any>(null),reason=ref(''),confirmation=ref(''),submitting=ref(false),dialogError=ref('');
let generation=0;
function statusLabel(status:string){return ({submitting:t('Submitting','提交中'),pending:t('Processing','处理中'),requiresAction:t('Provider action required','支付平台待处理'),unknown:t('Needs reconciliation — do not resubmit','待核对，请勿重复退款'),succeeded:t('Refund confirmed','退款已确认'),failed:t('Refund failed','退款失败'),canceled:t('Refund canceled','退款已取消'),rejected:t('Refund request not accepted','退款请求未受理'),completed:t('Paid','已付款')} as Record<string,string>)[status]||status;}
function failureHint(row:any){
  const kind=refundFailureKind(row);
  if(kind==='auth')return t('Provider authentication or permissions failed. Check the matching environment key and refund permissions.','支付平台认证或权限失败，请核对环境密钥与退款权限。');
  if(kind==='request')return t('The provider did not accept this request. Review the HTTP status and error code with provider support.','支付平台未受理本次请求，请结合 HTTP 状态和错误码向平台核实原因。');
  if(kind==='legacy')return t('This older request did not retain its error details; the exact cause cannot be recovered.','此旧请求未保留错误详情，无法还原具体失败原因。');
  if(kind==='uncertain')return t('The provider result needs review. Reconcile before any further action.','支付平台处理结果仍需核对，请先核对状态。');
  return '';
}
async function load(){const current=++generation;busy.value=true;error.value='';try{if(!session.value?.isAdmin)throw Error(t('Administrator access is required.','仅管理员可以访问。'));const result=await api('/admin/payments?'+new URLSearchParams({search:applied.value,page:String(page.value),size:String(size.value)}));if(current!==generation)return;rows.value=result.items;total.value=result.total;const last=Math.max(0,Math.ceil(total.value/size.value)-1);if(page.value>last){page.value=last;await load();}}catch(e){if(current===generation){error.value=errorText(e);rows.value=[];total.value=0;}}finally{if(current===generation)busy.value=false;}}
async function open(row:any){selected.value=row;quote.value=null;reason.value='';confirmation.value='';dialogError.value='';submitting.value=true;try{quote.value=await api(`/admin/payments/${encodeURIComponent(row.id)}/refund-preview`);}catch(e){dialogError.value=errorText(e);}finally{submitting.value=false;}}
async function refund(){if(submitting.value||!quote.value)return;submitting.value=true;dialogError.value='';try{const result=await api(`/admin/payments/${encodeURIComponent(selected.value.id)}/refund`,{confirmation:confirmation.value,reason:reason.value,amount:quote.value.amount,currency:quote.value.currency,cancelSubscription:quote.value.cancelSubscription});notice.value=statusLabel(result.status);if(result.cancellation_status==='unknown'||result.cancellation_status==='pending')notice.value+=' · '+t('Subscription cancellation needs reconciliation.','订阅取消仍需核对。');selected.value=null;await load();}catch(e){dialogError.value=errorText(e);}finally{submitting.value=false;}}
async function reconcile(row:any){busy.value=true;error.value='';try{const result=await api(`/admin/payments/${encodeURIComponent(row.id)}/refund-status`,{});notice.value=statusLabel(result.status);if(['pending','unknown'].includes(result.cancellation_status))notice.value+=' · '+t('Subscription cancellation needs reconciliation.','订阅取消仍需核对。');await load();}catch(e){error.value=errorText(e);}finally{busy.value=false;}}
watch(()=>props.refreshToken,load,{immediate:true});
</script>
<template><section class="panel admin-payments-panel" :aria-busy="busy">
  <p class="muted">{{t('Refund Creem payments within seven days. Review the provider amount before confirming; refunds and subscription cancellation are tracked separately.','处理付款后7天内的 Creem 全额退款。确认前核对支付平台金额；退款与订阅取消分别跟踪。')}}</p>
  <p class="muted">{{t('If a request fails, check its diagnostics below. For refunds made in Creem, reconcile here to sync confirmation and subscription cancellation. Reconciliation can cancel the linked subscription after a full refund is confirmed; it never submits another refund.','请求失败时请查看下方诊断信息。在 Creem 后台退款后，在此核对状态以同步退款确认及订阅取消；核对可能在全额退款确认后取消关联订阅，但不会重新发起退款。')}}</p>
  <form class="insight-toolbar" @submit.prevent="applied=search;page=0;load()"><label>{{t('Account or transaction','账号或交易编号')}}<input v-model="search" maxlength="256" :disabled="busy" /></label><button class="btn primary" :disabled="busy">{{t('Search','查询')}}</button></form>
  <p v-if="error" class="notice error" role="alert">{{error}}</p>
  <div class="table-wrap"><table><thead><tr><th>{{t('Account','账号')}}</th><th>{{t('Transaction','交易')}}</th><th>{{t('Provider','支付平台')}}</th><th>{{t('Amount','金额')}}</th><th>{{t('Payment / refund','付款 / 退款')}}</th><th>{{t('Recorded (UTC)','记录时间（UTC）')}}</th><th>{{t('Actions','操作')}}</th></tr></thead><tbody>
    <tr v-for="row in rows" :key="row.id"><td>{{row.email}}<br><small>{{row.workspace_name}}</small></td><td>{{row.id}}</td><td>{{row.payment_provider}}</td><td>{{row.amount??t('Unknown','未知')}} {{row.currency}}</td><td>{{statusLabel(row.refund_status||row.status)}}<div v-if="failureHint(row)" class="refund-diagnostic"><p>{{failureHint(row)}}</p><p v-if="row.provider_http_status">HTTP {{row.provider_http_status}} · {{row.provider_error_code}}</p><p v-if="row.provider_error_message">{{row.provider_error_message}}</p><p v-if="row.provider_error_stage">{{t('Stage','失败阶段')}}: {{row.provider_error_stage}} · {{date(row.provider_error_at)}}</p><p v-if="row.provider_error_request_id">{{t('Request ID','请求 ID')}}: {{row.provider_error_request_id}}</p><p>{{t('Do not repeat the refund. Verify the transaction in Creem and then reconcile here.','请勿重复退款。先在 Creem 核实交易，再回到此处核对状态。')}}</p></div><small v-if="['pending','unknown'].includes(row.cancellation_status)" class="error"><br>{{t('Cancellation needs reconciliation','订阅取消待核对')}}</small><small v-if="row.cancellation_status==='completed'"><br>{{t('Subscription canceled','订阅已取消')}}</small></td><td>{{date(row.created_at)}}</td><td><button v-if="row.payment_provider==='creem'&&row.id.startsWith('tran_')&&!row.refund_status&&row.status==='completed'" type="button" class="admin-refund-action" :disabled="busy" @click="open(row)">{{t('Refund','退款')}}</button><button v-else-if="row.refund_status" type="button" class="text-action" :disabled="busy" @click="reconcile(row)">{{t('Reconcile status','核对状态')}}</button><span v-else class="muted">{{t('Use provider dashboard','在支付平台处理')}}</span></td></tr>
    <tr v-if="!rows.length"><td colspan="7" class="empty-cell">{{busy?t('Loading…','加载中…'):t('No payments.','暂无付款记录。')}}</td></tr>
  </tbody></table></div><QueryControls :page="page" :size="size" :total="total" :loading="busy" @change="page=$event;load()" @resize="size=$event;page=0;load()" />
  <div v-if="selected" class="modal-backdrop" @keydown.esc="!submitting&&(selected=null)"><section class="modal admin-refund-modal" role="dialog" aria-modal="true" aria-labelledby="admin-refund-title"><h2 id="admin-refund-title">{{t('Confirm full refund','确认全额退款')}}</h2><p>{{selected.email}}<br>{{selected.id}}</p><p v-if="dialogError" class="notice error" role="alert">{{dialogError}}</p><p v-if="!quote&&submitting" role="status">{{t('Checking provider payment…','正在核对支付平台付款…')}}</p>
    <form v-if="quote" @submit.prevent="refund"><p><strong>{{quote.amount}} {{quote.currency}}</strong> · {{quote.mode==='test'?t('Test payment — no real money','测试支付，不涉及真实资金'):t('Live payment — money will be refunded','正式付款，将退还真实资金')}}</p><p>{{t('Paid at','付款时间')}}：{{date(quote.paidAt)}}<br>{{t('Refund deadline','退款截止')}}：{{date(quote.deadline)}}</p><p class="notice">{{quote.cancelSubscription?t('After refund confirmation, the linked subscription will be canceled immediately and the account returns to Free quota. Existing paid data follows the retention grace period.','退款确认后立即取消关联订阅，账号恢复 Free 额度；原付费数据按宽限期规则保留。'):t('This refunds the payment. No active subscription will be canceled.','本次退还付款，无需取消活跃订阅。')}} {{t('Provider acceptance does not mean funds have reached the bank account. Do not resubmit an uncertain result.','支付平台受理不代表银行立即到账；结果不明确时请勿重复退款。')}}</p>
    <label>{{t('Refund reason','退款原因')}}<textarea v-model="reason" maxlength="1000" required :disabled="submitting"></textarea></label><label>{{t('Enter the transaction ID to confirm','输入交易编号确认')}}<input v-model="confirmation" required autocomplete="off" :disabled="submitting" /></label><div class="admin-refund-buttons"><button class="btn danger-button" :disabled="submitting||confirmation!==selected.id||!reason.trim()">{{submitting?t('Submitting…','提交中…'):t('Confirm refund','确认退款')}}</button><button type="button" class="btn" :disabled="submitting" @click="selected=null">{{t('Cancel','取消')}}</button></div></form><button v-else type="button" class="btn" :disabled="submitting" @click="selected=null">{{t('Close','关闭')}}</button>
  </section></div>
</section></template>
